    id uuid not null,
    name text not null,
    client_id text not null,
    secret_hash text not null,
    scopes text[] not null default '{}',
    ip_allow text[] not null default '{}',
    rate_limit_per_minute integer not null,
    expires_at timestamptz,
    last_used_at timestamptz,
    status text not null,
    is_deleted boolean not null default false,
    deleted_at timestamptz,
    deleted_by uuid,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_api_clients primary key (id),
    constraint ck_api_clients_status check (status in ('active', 'revoked', 'expired'))
);
create unique index if not exists uq_api_clients_client_id on iam.api_clients (client_id) where (not is_deleted);

