    access_valid_to date,
    status text not null,
    is_deleted boolean not null default false,
    deleted_at timestamptz,
    deleted_by uuid,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_users primary key (id),
    constraint ck_users_status check (status in ('invited', 'active', 'locked', 'disabled', 'archived'))
);
create unique index if not exists uq_users_username on iam.users (lower(username)) where (not is_deleted);
create unique index if not exists uq_users_email on iam.users (lower(email)) where (not is_deleted);
create index if not exists ix_users_default_company_id on iam.users (default_company_id); -- foreign key fk_users_default_company_id

