comment on table iam.api_clients is 'API keys for integrations such as biometric middleware and HR data feeds (ADM-SEC-02); OAuth client credentials are Release 1.1. Requirements: ADM-SEC-02, KRN-INT-07. Source: kernel.yaml.';
comment on column iam.api_clients.secret_hash is 'shown once at creation';
comment on table iam.data_scopes is 'Reusable record filters (own, team, subtree, company, branch, department list). Requirements: KRN-IAM-12, ADM-ROL-06. Source: kernel.yaml.';
comment on column iam.data_scopes.definition is 'parameters for the kind';
comment on table iam.delegations is 'Approval delegation and out-of-office substitution. Requirements: KRN-WFL-05, ADM-ROL-09, HRM-ROL-05, HRM-SSP-07. Source: kernel.yaml.';
comment on column iam.delegations.from_user_id is 'fk iam.users';
comment on column iam.delegations.to_user_id is 'fk iam.users; check <> from_user_id';
comment on column iam.delegations.scope is 'document types, companies';
comment on table iam.field_policies is 'Field-level security per role. Requirements: KRN-IAM-13, ADM-ROL-07. Source: kernel.yaml.';
comment on column iam.field_policies.role_id is 'fk iam.roles';
comment on column iam.field_policies.field_key is 'includes custom fields';
comment on table iam.inbox_messages is 'Messages already processed by a consumer, so consumers are idempotent (spec 03 section 7.5). Source: spec 03 section 7.5.';
comment on table iam.login_attempts is 'Requirements: KRN-AUD-02. Source: kernel.yaml.';
comment on table iam.maker_checker_requests is 'Sensitive changes held for a second person. Requirements: KRN-IAM-14, ADM-SET-04, HRM-PAY-13. Source: kernel.yaml.';
comment on column iam.maker_checker_requests.requested_by is 'fk iam.users';
comment on column iam.maker_checker_requests.decided_by is 'fk iam.users; check <> requested_by';
comment on table iam.mfa_devices is 'Requirements: KRN-IAM-02, ADM-USR-21. Source: kernel.yaml.';
comment on column iam.mfa_devices.user_id is 'fk iam.users';
comment on table iam.outbox_messages is 'Events written in the business transaction; the dispatcher publishes them (spec 03 section 7.5). Source: spec 03 section 7.5.';
comment on table iam.password_history is 'Requirements: ADM-USR-20. Source: kernel.yaml.';
comment on column iam.password_history.user_id is 'fk iam.users';
comment on table iam.permissions is 'Registered from module manifests at start-up. Requirements: KRN-IAM-10, ADM-ROL-01. Source: kernel.yaml.';
comment on column iam.permissions.code is 'module.resource.action, e.g. hrm.payroll.approve';
comment on table iam.role_data_scopes is 'Requirements: KRN-IAM-12. Source: kernel.yaml.';
comment on column iam.role_data_scopes.role_id is 'fk iam.roles';
comment on column iam.role_data_scopes.resource_type is 'e.g. hrm.employment';
comment on column iam.role_data_scopes.data_scope_id is 'fk iam.data_scopes';
comment on table iam.role_permissions is 'Requirements: KRN-IAM-10. Source: kernel.yaml.';
comment on column iam.role_permissions.role_id is 'fk iam.roles';
comment on column iam.role_permissions.permission_id is 'fk iam.permissions';
comment on table iam.roles is 'Requirements: KRN-IAM-11, ADM-ROL-02, ADM-ROL-03. Source: kernel.yaml.';
comment on column iam.roles.baseline_code is 'baseline role it was copied from';
comment on table iam.sessions is 'Durable record of sign-in sessions (active copies cached in Valkey). Requirements: KRN-IAM-04, ADM-USR-24. Not strictly append-only: last_seen_at and revoked_* are updatable by the session service role only. Source: kernel.yaml.';
comment on column iam.sessions.user_id is 'fk iam.users';
comment on column iam.sessions.last_seen_at is 'updated by session service only (exception to append-only, documented)';
comment on table iam.user_credentials is 'Password hash kept apart from the user row. Requirements: KRN-IAM-01, ADM-USR-05, ADM-USR-20. Source: kernel.yaml.';
comment on column iam.user_credentials.user_id is 'pk, fk iam.users';
comment on column iam.user_credentials.failed_attempts is 'default 0';
comment on table iam.user_group_members is 'Requirements: ADM-USR-06. Source: kernel.yaml.';
comment on column iam.user_group_members.group_id is 'fk iam.user_groups';
comment on column iam.user_group_members.user_id is 'fk iam.users';
comment on table iam.user_groups is 'Requirements: ADM-USR-06. Source: kernel.yaml.';
comment on table iam.user_roles is 'Requirements: KRN-IAM-11, ADM-ROL-04. Source: kernel.yaml.';
comment on column iam.user_roles.user_id is 'fk iam.users';
comment on column iam.user_roles.role_id is 'fk iam.roles';
comment on column iam.user_roles.company_id is 'fk org.companies; null means all companies';
comment on table iam.users is 'People who sign in (employees, HR, admins). Requirements: KRN-IAM-01, ADM-USR-01, ADM-USR-03, ADM-USR-07. Source: kernel.yaml.';
comment on column iam.users.username is 'unique lower()';
comment on column iam.users.email is 'unique lower()';
comment on column iam.users.default_company_id is 'fk org.companies';
comment on column iam.users.language is 'en or ur in 1.0';
comment on column iam.users.time_zone is 'IANA, default Asia/Karachi';
comment on column iam.users.employee_ref is 'links to hrm.employments.id; no FK (module boundary)';
comment on column iam.users.is_system is 'reserved job and system users';
comment on column iam.users.access_valid_to is 'automatic disable date';
